input.command:
docker exec -i pocketos-db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1 <<'SQL' 2>&1
BEGIN;

-- Real schema drift: staging's checkout flow carries currency on orders.
-- Metadata-only in PG11+, so no rewrite of the 4,800 existing rows.
ALTER TABLE production.orders
    ADD COLUMN currency text NOT NULL DEFAULT 'USD';

-- The checkout release flag itself.
UPDATE production.app_config
   SET value = 'true', updated_at = now()
 WHERE key = 'feature.checkout_v2';

COMMIT;
SQL
